package ai.taskforge.domain;
import jakarta.persistence.*; import java.util.*;
@Entity @Table(name="workflow_steps",uniqueConstraints=@UniqueConstraint(columnNames={"workflow_id","stepOrder"})) public class WorkflowStep { @Id @GeneratedValue private UUID id; @ManyToOne(optional=false) @JoinColumn(name="workflow_id") private Workflow workflow; @Column(nullable=false) private int stepOrder; @Column(nullable=false) private String name; private String assigneeRole; private boolean approvalRequired; private int slaHours; protected WorkflowStep(){} public WorkflowStep(Workflow w,int o,String n,String r,boolean a,int sla){workflow=w;stepOrder=o;name=n;assigneeRole=r;approvalRequired=a;slaHours=sla;} public UUID getId(){return id;} public int getStepOrder(){return stepOrder;} public String getName(){return name;} public String getAssigneeRole(){return assigneeRole;} public boolean isApprovalRequired(){return approvalRequired;} public int getSlaHours(){return slaHours;} }
